    {
        if (pos == 1)
        {
            struct node *p;
            p = start;
            start = start->link;
            free(p);
        }
        else
        {
            struct node *prev = start;
            for (int i = 2; i < pos; i++)
            {
                if (prev == NULL)
                {
                    printf("Position not found!");
                    return 0;
                }
                prev = prev->link;
            }
